#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    string password;
    cin >> password;

    vector<array<int, 26>> freq(M);
    for (int i = 0; i < M; ++i) {
        string s;
        cin >> s;
        freq[i].fill(0);
        for (char c : s) ++freq[i][c - 'a'];
    }

    long long P;
    cin >> P;
    const long long cap = P;

    auto mulCap = [&](long long a, long long b) {
        if (a == 0 || b == 0) return 0LL;
        if (a > cap / b) return cap;
        return min(cap, a * b);
    };

    vector<long long> powers(M + 1, 1);
    for (int i = 1; i <= M; ++i)
        powers[i] = mulCap(powers[i - 1], K);

    long long prefixMultiplicity = 1;
    int hashIndex = 0;

    for (int i = 0; i < N; ++i) {
        if (password[i] != '#') continue;

        int remaining = M - hashIndex - 1;
        for (int c = 0; c < 26; ++c) {
            if (freq[hashIndex][c] == 0) continue;

            long long count = mulCap(prefixMultiplicity, freq[hashIndex][c]);
            count = mulCap(count, powers[remaining]);

            if (P > count) {
                P -= count;
            } else {
                password[i] = char('a' + c);
                prefixMultiplicity = mulCap(prefixMultiplicity, freq[hashIndex][c]);
                break;
            }
        }

        ++hashIndex;
    }

    cout << password << '\n';
    return 0;
}
